const postback = $input.first().json.postback || '';

const parts = postback.split('|');
const baseDrink = parts[0] || null;
const size = parts[1] || null;
let addOn = parts[2] || null;
if (addOn?.startsWith('ADD_')) addOn = addOn.slice(4);
const Bite = parts.find(p => p.includes('BK')) || (postback.includes('BK') ? postback : null);

return {
  json: { postback, baseDrink, size, addOn, Bite }
};

const drinkData = $('fetch baseDrink').first().json;
const extractedData = $('extract values').first().json;

let addOnData = null;
try {
  const addOnNode = $('fetch add-on').first();
  addOnData = addOnNode ? addOnNode.json : null;
} catch {
  addOnData = null;
}

const senderId = $('Listen').first().json.senderId;

if (extractedData.Bite) {
  const bitesData = $('fetch bites').first().json;

  if (!bitesData || Object.keys(bitesData).length === 0) {
    return [{
      json: {
        success: false,
        message: `Sorry, the bites "${extractedData.Bite}" is not available.`,
        code: 'BITES_NOT_FOUND',
        senderId
      }
    }];
  }

  if (bitesData.Quantity <= 0 || !bitesData.IsEnabled) {
    return [{
      json: {
        success: false,
        message: `Sorry, ${bitesData.Name} is currently out of stock. Please choose a different item.`,
        code: 'BITES_OUT_OF_STOCK',
        senderId
      }
    }];
  }

  return [{
    json: {
      success: true,
      message: `${bitesData.Name} is available.`,
      bitesData,
      senderId
    }
  }];
}

if (!drinkData || Object.keys(drinkData).length === 0) {
  return [{
    json: {
      success: false,
      message: `Sorry, the drink "${extractedData.baseDrink}" is not available in our menu.`,
      code: 'PRODUCT_NOT_FOUND',
      senderId
    }
  }];
}

let validatedAddOnData = null;

if (extractedData.addOn && extractedData.addOn !== 'NONE') {
  if (!addOnData || Object.keys(addOnData).length === 0) {
    return [{
      json: {
        success: false,
        message: `Sorry, the selected add-on "${extractedData.addOn}" is not available.`,
        code: 'ADDON_NOT_FOUND',
        senderId
      }
    }];
  }

  if (addOnData.Quantity <= 0 || !addOnData.IsEnabled) {
    return [{
      json: {
        success: false,
        message: `Sorry, ${addOnData.Name} is currently out of stock. Please choose a different add-on.`,
        code: 'ADDON_OUT_OF_STOCK',
        senderId
      }
    }];
  }

  validatedAddOnData = addOnData;
} else {
  validatedAddOnData = {
    AddOnID: 'NONE',
    Name: 'No Add-on',
    Price: 0,
    Quantity: Infinity,
    IsEnabled: true
  };
}

return [{
  json: {
    drinkData,
    addOnData: validatedAddOnData,
    extractedData,
    senderId,
    ingredients: drinkData.Ingredients || []
  }
}];

let allIngredientStocks = [];
try {
  const ingredientStockNodes = $('fetch ingredients stock').all();
  allIngredientStocks = ingredientStockNodes?.length
    ? ingredientStockNodes.map(item => item.json)
    : [];
} catch {
  allIngredientStocks = [];
}

let drinkData = null;
try {
  drinkData = $('fetch baseDrink').first().json;
} catch {
  drinkData = null;
}

let addOnData = null;
try {
  addOnData = $('fetch add-on').first()?.json || null;
} catch {
  addOnData = null;
}

let extractedData = null;
try {
  extractedData = $('extract values').first().json;
} catch {
  extractedData = null;
}

let senderId = 'unknown_user';
try {
  senderId = $('Listen').first().json.senderId || senderId;
} catch {}

if (!drinkData || !extractedData) {
  return [{
    json: {
      success: false,
      message: 'Missing essential order data. Please try again.',
      code: 'MISSING_DATA',
      senderId
    }
  }];
}

if ((!addOnData || Object.keys(addOnData).length === 0) && (!extractedData.addOn || extractedData.addOn === 'NONE')) {
  addOnData = {
    AddOnID: 'NONE',
    Name: 'No Add-on',
    Price: 0,
    Quantity: Infinity,
    IsEnabled: true
  };
}

let requiredIngredients = drinkData.Ingredients || [];

if (!Array.isArray(requiredIngredients)) {
  requiredIngredients = requiredIngredients ? [requiredIngredients] : [];
}

if (requiredIngredients.length > 0 && allIngredientStocks.length === 0) {
  return [{
    json: {
      success: false,
      message: 'Unable to check ingredient availability. Please try again later.',
      code: 'STOCK_DATA_UNAVAILABLE',
      senderId
    }
  }];
}

const unavailableIngredients = [];

for (const ingredientId of requiredIngredients) {
  if (!ingredientId) continue;

  const stock = allIngredientStocks.find(item => item.IngredientID === ingredientId);

  if (
    !stock ||
    stock.Quantity === undefined ||
    stock.Quantity <= 0 ||
    !stock.IsEnabled
  ) {
    unavailableIngredients.push({
      ingredientId,
      name: stock?.Name || 'Unknown Ingredient',
      available: false,
      quantity: stock?.Quantity ?? 0,
      enabled: stock?.IsEnabled ?? false
    });
  }
}

if (unavailableIngredients.length > 0) {
  const names = unavailableIngredients.map(i => i.name).join(', ');
  return [{
    json: {
      success: false,
      message: `Sorry, "${drinkData.Name}" is unavailable due to insufficient stock of: ${names}`,
      code: 'INSUFFICIENT_INGREDIENTS',
      unavailableIngredients,
      senderId
    }
  }];
}

function createCartItem({
  userId,
  productId,
  productName,
  addOnId,
  addOnName,
  quantity = 1,
  basePrice = 0,
  addOnPrice = 0,
  status = 'pending'
}) {
  const totalPrice = basePrice + addOnPrice;
  return {
    userId,
    productId,
    productName,
    addOnId,
    addOnName,
    quantity,
    basePrice,
    addOnPrice,
    totalPrice,
    createdAt: new Date().toISOString(),
    status
  };
}

const basePrice = drinkData.Sizes?.[0]?.BasePrice || 0;
const addOnPrice = addOnData?.BasePrice || 0;

const cartItem = createCartItem({
  userId: senderId,
  productId: extractedData.baseDrink,
  productName: drinkData.Name,
  addOnId: extractedData.addOn || 'NONE',
  addOnName: addOnData.Name || 'No Add-on',
  basePrice,
  addOnPrice
});

return [{
  json: {
    success: true,
    message: `Great! '${drinkData.Name}' with '${addOnData?.Name || 'No Add-on'}' has been added to your cart.`,
    code: 'ORDER_ADDED_TO_CART',
    cartItem,
    pricing: {
      basePrice,
      addOnPrice,
      totalPrice: cartItem.totalPrice
    },
    senderId
  }
}];

const postback = $json.latestPostback || $json.postback;
const productId = postback.replace('ADD_', '');

return [{ json: { productId } }];

const product = $input.first().json;
const sizes = Array.isArray(product.Sizes) ? product.Sizes : [];
const senderId = $('Listen').first().json.senderId;
const priceFormat = p => (p ? `₱${p}` : '');
if (sizes.length === 0) {
  return [{
    json: {
      sendSizeButtons: false,
      sizeSelected: false,
      message: `Selected: ${product.Name} (${priceFormat(product.BasePrice)}). Added to cart!`,
      senderId
    }
  }];
}
const buttons = sizes.map(s => ({
  type: "postback",
  title: `${s.Size} - ${priceFormat(s.BasePrice)}`,
  payload: `${product.ProductID}|${s.Size}`
}));
return [{
  json: {
    sendSizeButtons: true,
    sizeSelected: false,
    recipient_id: senderId,
    message: `Choose a size for your ${product.Name}:`,
    buttons
  }
}];

